import json
import urllib.request
import urllib.error

class OpenAIClient:
    \"\"\"A minimal client for OpenAI's Responses API using only the standard library.\"\"\"

    def __init__(self, api_key: str, base_url: str = \"https://api.openai.com/v1\"):
        self.api_key = api_key
        self.base_url = base_url

    def send_prompt(self, prompt: str, model: str = \"gpt-4o\"):
        \"\"\"Sends a private text prompt to the Responses API.\"\"\"
        url = f\"{self.base_url}/chat/completions\"

        headers = {
            \"Content-Type\": \"application/json\",
            \"Authorization\": f\"Bearer {self.api_key}\"
        }

        data = {
            \"model\": model,
            \"messages\": [{\"role\": \"user\", \"content\": prompt}]
        }

        body = json.dumps(data).encode(\"utf-8\")

        try:
            req = urllib.request.Request(url, data=body, headers=headers)
            with urllib.request.urlopen(req) as response:
                return json.loads(response.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as e:
            print(f\"HTTP Error: {e.code} - {e.read().decode('utf-8')}\")
            raise
        except urllib.error.URLError as e:
            print(f\"URL Error: {e.reason}\")
            raise

if __name__ == \"__main__\":
    # Example usage:
    # client = OpenAIClient(api_key=\"your-api-key\")
    # print(client.send_prompt(\"Hello, how are you?\"))
    pass
EOF
"

